package grading.scoring;

import java.util.Locale;
import java.util.OptionalDouble;

/** Formats marks the same way everywhere they are shown: one decimal place, such as 8.5. */
public final class Marks {

    private Marks() {
    }

    public static String format(double marks) {
        return String.format(Locale.ROOT, "%.1f", marks);
    }

    /** Such as "8.5/20", or just "8.5" when the most possible is not known. */
    public static String outOf(double marks, OptionalDouble most) {
        if (most.isEmpty()) {
            return format(marks);
        }
        return format(marks) + "/" + most(most.getAsDouble());
    }

    /** The most marks possible, without a decimal when it is whole: "20", or "2.5". */
    public static String most(double most) {
        return most == Math.rint(most) ? String.valueOf((long) most) : format(most);
    }
}
